12	/// A light wrapper around timeline items returned from Rust.
13	enum TimelineItemProxy {
14	    case event(EventTimelineItemProxy)
15	    case virtual(MatrixRustSDK.VirtualTimelineItem, uniqueID: TimelineItemIdentifier.UniqueID)
16	    case unknown(MatrixRustSDK.TimelineItem)
17	    
18	    init(item: MatrixRustSDK.TimelineItem) {
19	        if let eventItem = item.asEvent() {
20	            self = .event(EventTimelineItemProxy(item: eventItem, uniqueID: .init(rustValue: item.uniqueId())))
21	        } else if let virtualItem = item.asVirtual() {
22	            self = .virtual(virtualItem, uniqueID: .init(rustValue: item.uniqueId()))
23	        } else {
24	            self = .unknown(item)
25	        }
26	    }
27	    
28	    var isEvent: Bool {
29	        switch self {
30	        case .event:
31	            return true
32	        default:
33	            return false
34	        }
35	    }
36	}
