38	/// The delivery status for the item.
39	enum TimelineItemDeliveryStatus: Hashable {
40	    case sending
41	    case sent
42	    case sendingFailed(TimelineItemSendFailure)
43	    
44	    var isSendingFailed: Bool {
45	        switch self {
46	        case .sending, .sent: false
47	        case .sendingFailed: true
48	        }
49	    }
50	}
