136	struct TimelineItemDebugInfo: Identifiable, CustomStringConvertible {
137	    let id = UUID()
138	    let model: String
139	    let originalJSON: String?
140	    let latestEditJSON: String?
141	    
142	    init(model: String, originalJSON: String?, latestEditJSON: String?) {
143	        self.model = model
144	        
145	        self.originalJSON = Self.prettyJsonFormattedString(from: originalJSON)
146	        self.latestEditJSON = Self.prettyJsonFormattedString(from: latestEditJSON)
147	    }
148	    
149	    var description: String {
150	        var description = model
151	        
152	        if let originalJSON {
153	            description += "\n\n\(originalJSON)"
